diff --git a/src/lib/onboardingSaga.ts b/src/lib/onboardingSaga.ts
@@ -0,0 +1,62 @@
+export class OnboardingSaga {
+  private steps: Array<{
+    service: string;
+    action: () => Promise<void>;
+    compensate: () => Promise<void>;
+  }> = [];
+
+  addStep(service: string, action: () => Promise<void>, compensate: () => Promise<void>) {
+    this.steps.push({ service, action, compensate });
+  }
+
+  async execute() {
+    const completed: number[] = [];
+    for (let i = 0; i < this.steps.length; i++) {
+      try {
+        await this.steps[i].action();
+        completed.push(i);
+      } catch (err) {
+        for (let j = completed.length - 1; j >= 0; j--) {
+          await this.steps[j].compensate();
+        }
+        throw err;
+      }
+    }
+  }
+}
